// SmartFlow Myanmar design reminder: Night Operations Ledger — restrained midnight navy, cyan workflow signal, green completion signal, dense but readable admin workspace. Data-first screens must show real Supabase records or clear empty states; never fabricate customer activity.
import { useEffect, useMemo, useState, type ReactNode } from "react";
import { Toaster, toast } from "sonner";
import { createClient, type Session, type SupabaseClient } from "@supabase/supabase-js";
import {
  Activity, Archive, ArrowUpRight, BarChart3, Bell, CalendarClock, Check, ChevronRight,
  CircleDollarSign, ClipboardList, Clock3, Filter, LayoutDashboard, LogOut, Mail,
  Menu, Package, Pencil, Phone, Plus, RefreshCw, Search, Settings2, Tag, UserRound,
  Users, X, Zap, LoaderCircle, Smartphone, Wrench, Boxes, WalletCards, ShieldCheck,
} from "lucide-react";
import "./index.css";

type Status = "lead" | "active" | "inactive" | "archived";
type OrderStatus = "new" | "processing" | "confirmed" | "completed" | "cancelled";
type Channel = "Messenger" | "Viber" | "Website" | "Phone" | "Other";
type Customer = { id: string; full_name: string; phone: string; email: string; company: string; status: Status; source: Channel; notes: string; tags: string[]; last_touch: string | null; created_at: string; };
type Order = { id: string; customer_id: string; order_number: string; amount: number; status: OrderStatus; channel: Channel; created_at: string; customer?: Customer };
type ActivityItem = { id: string; customer_id: string; order_id?: string | null; type: "note" | "call" | "meeting" | "email"; title: string; description: string; activity_at: string; };
type FollowUpStatus = "pending" | "completed" | "snoozed" | "cancelled";
type FollowUpPriority = "low" | "normal" | "high" | "urgent";
type FollowUp = { id: string; customer_id: string; order_id?: string | null; title: string; note: string; due_at: string; status: FollowUpStatus; priority: FollowUpPriority; completed_at?: string | null; customer?: Customer };
type Product = { id: string; sku: string; brand: string; model: string; storage: string; color: string; condition: "new" | "used" | "refurbished"; imei: string; cost_price: number; selling_price: number; quantity: number; reorder_level: number; warranty_months: number; supplier_name: string; created_at: string; };
type Repair = { id: string; customer_id: string; device_name: string; imei: string; issue: string; status: "received" | "diagnosing" | "repairing" | "ready" | "collected"; estimated_cost: number; due_at: string | null; notes: string; created_at: string; customer?: Customer };
type View = "overview" | "customers" | "orders" | "followups" | "inventory" | "repairs";

// Preview-safe public client fallback: these are browser-safe Supabase project values,
// never service-role credentials. GitHub Actions variables still take precedence.
const supabaseUrl = (import.meta.env.VITE_SUPABASE_URL as string | undefined) || "https://wkahfwfpmifcdxycajtu.supabase.co";
const supabaseKey = (import.meta.env.VITE_SUPABASE_ANON_KEY as string | undefined) || "sb_publishable_U-UKVWvtUpuviVWFfhjiNw_cv5KMIeT";
const supabase: SupabaseClient | null = supabaseUrl && supabaseKey ? createClient(supabaseUrl, supabaseKey, { auth: { persistSession: false, autoRefreshToken: true, detectSessionInUrl: false } }) : null;
const logo = `${import.meta.env.BASE_URL}smartflow-logo.png`;

const statusMeta: Record<Status, { en: string; my: string; tone: string }> = {
  lead: { en: "Lead", my: "စောင့်ကြည့်ရန်", tone: "amber" },
  active: { en: "Active", my: "လုပ်ဆောင်နေ", tone: "green" },
  inactive: { en: "Inactive", my: "မလုပ်ဆောင်သေး", tone: "slate" },
  archived: { en: "Archived", my: "သိမ်းဆည်းထား", tone: "rose" },
};
const orderMeta: Record<OrderStatus, { en: string; my: string; tone: string }> = {
  new: { en: "New", my: "အသစ်", tone: "cyan" },
  processing: { en: "Processing", my: "လုပ်ဆောင်နေ", tone: "amber" },
  confirmed: { en: "Confirmed", my: "အတည်ပြုပြီး", tone: "green" },
  completed: { en: "Completed", my: "ပြီးစီး", tone: "violet" },
  cancelled: { en: "Cancelled", my: "ပယ်ဖျက်", tone: "rose" },
};
const channels: Channel[] = ["Messenger", "Viber", "Website", "Phone", "Other"];
const orderStatuses: OrderStatus[] = ["new", "processing", "confirmed", "completed", "cancelled"];

function formatDate(value?: string | null, language: "en" | "my" = "en") {
  if (!value) return language === "my" ? "မှတ်တမ်းမရှိသေးပါ" : "No activity yet";
  return new Intl.DateTimeFormat(language === "my" ? "my-MM" : "en-US", { dateStyle: "medium", timeStyle: "short" }).format(new Date(value));
}
function initials(name: string) { return name.split(" ").map((part) => part[0]).join("").slice(0, 2).toUpperCase(); }
function money(amount: number) { return `${new Intl.NumberFormat("en-US").format(amount)} K`; }
function toneClass(tone: string) { return `status-badge tone-${tone}`; }

function App() { return <AuthGate />; }

function AuthGate() {
  const [session, setSession] = useState<Session | null>(null);
  const [checking, setChecking] = useState(Boolean(supabase));
  const [adminDenied, setAdminDenied] = useState(false);
  const [email, setEmail] = useState(""); const [password, setPassword] = useState("");
  const [submitting, setSubmitting] = useState(false); const [language, setLanguage] = useLanguage(); const [error, setError] = useState("");
  const t = (en: string, my: string) => language === "my" ? my : en;
  useEffect(() => {
    if (!supabase) { setChecking(false); return; }
    let mounted = true;
    supabase.auth.getSession().then(async ({ data }) => { if (!mounted) return; if (data.session) { const { data: admin, error: adminError } = await supabase.from("admin_users").select("user_id").eq("user_id", data.session.user.id).maybeSingle(); if (adminError || !admin) setAdminDenied(true); else setSession(data.session); } setChecking(false); });
    const { data } = supabase.auth.onAuthStateChange(async (_event, next) => { if (!mounted) return; if (!next) { setSession(null); setAdminDenied(false); return; } const { data: admin, error: adminError } = await supabase.from("admin_users").select("user_id").eq("user_id", next.user.id).maybeSingle(); if (adminError || !admin) setAdminDenied(true); else setSession(next); });
    return () => { mounted = false; data.subscription.unsubscribe(); };
  }, []);
  async function signIn(event: React.FormEvent) {
    event.preventDefault(); if (!supabase) return; setSubmitting(true); setError("");
    const { error: authError } = await supabase.auth.signInWithPassword({ email: email.trim(), password });
    if (authError) setError(authError.message.toLowerCase().includes("fetch") ? t("Supabase could not be reached. Check GitHub Actions secrets.", "Supabase server သို့ မရောက်နိုင်ပါ။ GitHub Actions secrets ကို စစ်ဆေးပါ။") : authError.message);
    setSubmitting(false);
  }
  async function signOut() { if (supabase) await supabase.auth.signOut(); setSession(null); }
  if (!supabase) return <AuthMessage language={language} />;
  if (checking) return <div className="auth-screen"><div className="auth-loading"><LoaderCircle className="spin" /> {t("Checking admin session…", "Admin session ကို စစ်ဆေးနေပါသည်…")}</div></div>;
  if (adminDenied) return <div className="auth-screen"><div className="auth-panel"><img className="auth-logo" src={logo} alt="SmartFlow Myanmar" /><span className="kicker">ADMIN ACCESS ONLY</span><h1>{t("This account is not on the admin list.", "ဤ account သည် Admin စာရင်းတွင် မပါဝင်ပါ။")}</h1><p>{t("Ask the workspace owner to add your Supabase Auth user ID to public.admin_users, then sign in again.", "Supabase Auth user ID ကို public.admin_users ထဲသို့ ထည့်ပေးရန် workspace owner ကို ပြောပြီး ပြန်ဝင်ပါ။")}</p><button className="secondary-button" onClick={() => void signOut()}><LogOut size={15} />{t("Use another account", "အခြား account သုံးရန်")}</button></div></div>;
  if (session) return <Dashboard session={session} onSignOut={signOut} />;
  return <div className="auth-screen"><form className="auth-panel" onSubmit={signIn}><div className="auth-brand"><div className="auth-brand-mark"><img src={logo} alt="SmartFlow Myanmar" /></div><div className="auth-brand-copy"><strong>SmartFlow Myanmar</strong><span>OPERATIONS CONSOLE</span></div><button type="button" className="lang-toggle" onClick={() => setLanguage(language === "en" ? "my" : "en")}>{language === "en" ? "မြန်မာ" : "English"}</button></div><div className="auth-orbit-label"><span className="signal-line" /> SMARTFLOW / PRIVATE ADMIN WORKSPACE</div><h1>{t("Keep every customer move visible.", "ဖောက်သည်တိုင်း၏ လုပ်ဆောင်ချက်ကို တစ်နေရာတည်းတွင် စောင့်ကြည့်ပါ။")}</h1><p>{t("A focused command center for customer context, order progress, and the next follow-up.", "ဖောက်သည်အချက်အလက်၊ order တိုးတက်မှုနှင့် နောက်ဆက်တွဲလုပ်ဆောင်ချက်များကို စီမံရန် အာရုံစိုက်ထားသော workspace ဖြစ်ပါသည်။")}</p><div className="auth-signal"><span><i className="connected-dot" /> {t("SECURE ADMIN ACCESS", "လုံခြုံသော ADMIN ဝင်ခွင့်")}</span><span>{t("SUPABASE / READY", "SUPABASE / အသင့်")}</span></div><label>{t("Admin email", "Admin အီးမေးလ်")}<div className="input-wrap"><Mail size={16} /><input required type="email" value={email} onChange={(e) => setEmail(e.target.value)} placeholder="admin@example.com" /></div></label><label>{t("Password", "စကားဝှက်")}<div className="input-wrap"><span className="input-lock">••</span><input required type="password" value={password} onChange={(e) => setPassword(e.target.value)} placeholder="••••••••" /></div></label>{error && <div className="error-banner">{error}</div>}<button className="primary-button auth-button" disabled={submitting}>{submitting ? <LoaderCircle className="spin" size={16} /> : <Zap size={16} />}{t("Enter admin console", "Admin console သို့ ဝင်ရန်")}</button><small>{t("Admin access only · SmartFlow Myanmar", "Admin သီးသန့် · SmartFlow Myanmar")}</small></form></div>;
}
function AuthMessage({ language }: { language: "en" | "my" }) { return <div className="auth-screen"><div className="auth-panel"><img className="auth-logo" src={logo} alt="SmartFlow Myanmar" /><span className="kicker">CONFIGURATION REQUIRED</span><h1>{language === "my" ? "Supabase ကို ချိတ်ဆက်ပါ။" : "Connect Supabase before signing in."}</h1><p>{language === "my" ? "Preview environment တွင် public Supabase configuration မရရှိသေးပါ။ Project settings သို့မဟုတ် GitHub Actions တွင် VITE_SUPABASE_URL နှင့် VITE_SUPABASE_ANON_KEY ကို စစ်ဆေးပြီး redeploy လုပ်ပါ။" : "The Preview environment has no public Supabase configuration. Check VITE_SUPABASE_URL and VITE_SUPABASE_ANON_KEY in project settings or GitHub Actions, then redeploy."}</p></div></div>; }
function useLanguage(): ["en" | "my", (value: "en" | "my") => void] { const [language, set] = useState<"en" | "my">(() => (localStorage.getItem("smartflow-language") as "en" | "my") || "my"); return [language, (value) => { set(value); localStorage.setItem("smartflow-language", value); }]; }

function Dashboard({ session, onSignOut }: { session: Session; onSignOut: () => Promise<void> }) {
  const [view, setView] = useState<View>(() => window.location.pathname.includes("follow") ? "followups" : window.location.pathname.includes("order") ? "orders" : window.location.pathname.includes("customer") ? "customers" : window.location.pathname.includes("inventory") ? "inventory" : window.location.pathname.includes("repair") ? "repairs" : "overview");
  const [language, setLanguage] = useLanguage(); const t = (en: string, my: string) => language === "my" ? my : en;
  const [customers, setCustomers] = useState<Customer[]>([]); const [orders, setOrders] = useState<Order[]>([]); const [activities, setActivities] = useState<ActivityItem[]>([]); const [followupRecords, setFollowupRecords] = useState<FollowUp[]>([]); const [products, setProducts] = useState<Product[]>([]); const [repairs, setRepairs] = useState<Repair[]>([]);
  const [query, setQuery] = useState(""); const [statusFilter, setStatusFilter] = useState<Status | "all">("all"); const [orderFilter, setOrderFilter] = useState<OrderStatus | "all">("all");
  const [selectedCustomer, setSelectedCustomer] = useState<Customer | null>(null); const [mobileOpen, setMobileOpen] = useState(false); const [showCustomerForm, setShowCustomerForm] = useState(false); const [showOrderForm, setShowOrderForm] = useState(false); const [showFollowupForm, setShowFollowupForm] = useState(false); const [showProductForm, setShowProductForm] = useState(false); const [showRepairForm, setShowRepairForm] = useState(false); const [editing, setEditing] = useState<Customer | null>(null); const [loading, setLoading] = useState(true); const [syncing, setSyncing] = useState(false);
  async function loadData() { if (!supabase) return; setSyncing(true); const [customerResult, orderResult, activityResult, followupResult, productResult, repairResult] = await Promise.all([supabase.from("customers").select("*").order("created_at", { ascending: false }), supabase.from("orders").select("*, customer:customers(*)").order("created_at", { ascending: false }), supabase.from("activities").select("*").order("activity_at", { ascending: false }).limit(100), supabase.from("follow_ups").select("*, customer:customers(*)").eq("status", "pending").order("due_at", { ascending: true }), supabase.from("products").select("*").order("created_at", { ascending: false }), supabase.from("repairs").select("*, customer:customers(*)").neq("status", "collected").order("created_at", { ascending: false })]); if (customerResult.error) toast.error(t("Customers table could not be loaded.", "Customers table ကို မဖတ်နိုင်ပါ။")); if (orderResult.error && !orderResult.error.message.includes("relation")) toast.error(t("Orders table could not be loaded.", "Orders table ကို မဖတ်နိုင်ပါ။")); if (activityResult.error && !activityResult.error.message.includes("relation")) toast.error(t("Activities table could not be loaded.", "Activities table ကို မဖတ်နိုင်ပါ။")); if (followupResult.error && !followupResult.error.message.includes("relation")) toast.error(t("Follow-up queue could not be loaded.", "နောက်ဆက်တွဲတန်းစီမှုကို မဖတ်နိုင်ပါ။")); if (productResult.error && !productResult.error.message.includes("relation")) toast.error(t("Inventory table could not be loaded.", "Inventory table ကို မဖတ်နိုင်ပါ။")); if (repairResult.error && !repairResult.error.message.includes("relation")) toast.error(t("Repair queue could not be loaded.", "ပြုပြင်ရေးတန်းစီမှုကို မဖတ်နိုင်ပါ။")); setCustomers((customerResult.data ?? []) as Customer[]); setOrders((orderResult.data ?? []) as Order[]); setActivities((activityResult.data ?? []) as ActivityItem[]); setFollowupRecords((followupResult.data ?? []) as FollowUp[]); setProducts((productResult.data ?? []) as Product[]); setRepairs((repairResult.data ?? []) as Repair[]); setLoading(false); setSyncing(false); }
  useEffect(() => { void loadData(); }, []);
  const filteredCustomers = useMemo(() => customers.filter((customer) => { const haystack = `${customer.full_name} ${customer.company} ${customer.email} ${customer.phone} ${customer.tags?.join(" ")}`.toLowerCase(); return haystack.includes(query.toLowerCase()) && (statusFilter === "all" || customer.status === statusFilter); }), [customers, query, statusFilter]);
  const filteredOrders = useMemo(() => orders.filter((order) => { const customerName = order.customer?.full_name ?? ""; return `${order.order_number} ${customerName} ${order.channel}`.toLowerCase().includes(query.toLowerCase()) && (orderFilter === "all" || order.status === orderFilter); }), [orders, query, orderFilter]);
  const followups = customers.filter((customer) => customer.tags?.some((tag) => tag.toLowerCase().includes("follow")) || customer.status === "lead"); const liveFollowups = followupRecords;
  const stats = { customers: customers.filter((c) => c.status !== "archived").length, active: customers.filter((c) => c.status === "active").length, orders: orders.length, revenue: orders.filter((o) => o.status !== "cancelled").reduce((sum, o) => sum + Number(o.amount || 0), 0), units: products.reduce((sum, product) => sum + Number(product.quantity || 0), 0), lowStock: products.filter((product) => Number(product.quantity || 0) <= Number(product.reorder_level || 0)).length, openRepairs: repairs.length };
  async function saveCustomer(input: Omit<Customer, "id" | "created_at">) { if (!supabase) return; setSyncing(true); const result = editing ? await supabase.from("customers").update(input).eq("id", editing.id) : await supabase.from("customers").insert(input); if (result.error) toast.error(result.error.message); else { toast.success(t("Customer saved.", "ဖောက်သည်မှတ်တမ်း သိမ်းပြီးပါပြီ။")); setShowCustomerForm(false); setEditing(null); await loadData(); } setSyncing(false); }
  async function saveOrder(input: Omit<Order, "id" | "created_at" | "customer">) { if (!supabase) return; const result = await supabase.from("orders").insert(input); if (result.error) toast.error(result.error.message); else { toast.success(t("Order added.", "Order ထည့်ပြီးပါပြီ။")); setShowOrderForm(false); await loadData(); } }
  async function updateOrder(order: Order, status: OrderStatus) { if (!supabase) return; const result = await supabase.from("orders").update({ status, updated_at: new Date().toISOString() }).eq("id", order.id); if (result.error) toast.error(result.error.message); else await loadData(); } async function saveFollowup(input: Omit<FollowUp, "id" | "created_at" | "updated_at" | "customer">) { if (!supabase) return; const result = await supabase.from("follow_ups").insert(input); if (result.error) toast.error(result.error.message); else { toast.success(t("Follow-up added.", "နောက်ဆက်တွဲ မှတ်တမ်းထည့်ပြီးပါပြီ။")); setShowFollowupForm(false); await loadData(); } } async function saveProduct(input: Omit<Product, "id" | "created_at">) { if (!supabase) return; const result = await supabase.from("products").insert(input); if (result.error) toast.error(result.error.message); else { toast.success(t("Device added to inventory.", "ဖုန်း stock ထဲသို့ ထည့်ပြီးပါပြီ။")); setShowProductForm(false); await loadData(); } } async function saveRepair(input: Omit<Repair, "id" | "created_at" | "customer">) { if (!supabase) return; const result = await supabase.from("repairs").insert(input); if (result.error) toast.error(result.error.message); else { toast.success(t("Repair ticket created.", "ပြုပြင်ရေးမှတ်တမ်း ဖန်တီးပြီးပါပြီ။")); setShowRepairForm(false); await loadData(); } }
  function exportCsv() { const rows = customers.map((customer) => ({ name: customer.full_name, company: customer.company || "", phone: customer.phone || "", email: customer.email || "", status: customer.status, source: customer.source, open_followups: followupRecords.filter((followup) => followup.customer_id === customer.id).length })); const header = Object.keys(rows[0] || { name: "", company: "", phone: "", email: "", status: "", source: "", open_followups: "" }); const csv = [header.join(","), ...rows.map((row) => header.map((key) => `"${String(row[key as keyof typeof row] ?? "").replaceAll('"', '""')}"`).join(","))].join("\n"); const blob = new Blob([csv], { type: "text/csv;charset=utf-8" }); const url = URL.createObjectURL(blob); const anchor = document.createElement("a"); anchor.href = url; anchor.download = `smartflow-customers-${new Date().toISOString().slice(0, 10)}.csv`; anchor.click(); URL.revokeObjectURL(url); toast.success(t("Customer CSV exported.", "ဖောက်သည် CSV ထုတ်ယူပြီးပါပြီ။")); } const nav = (next: View) => { setView(next); setMobileOpen(false); window.history.replaceState({}, "", next === "overview" ? "/" : `/${next}`); };
  return <div className="console-shell"><Toaster position="bottom-right" theme="dark" /><aside className={`console-sidebar ${mobileOpen ? "open" : ""}`}><div className="console-brand"><img src={logo} alt="SmartFlow Myanmar" /><div><strong>SmartFlow</strong><span>MYANMAR · ADMIN</span></div></div><div className="sidebar-label">{t("Workspace", "လုပ်ငန်းခွင်")}</div><nav className="console-nav"><NavButton icon={<LayoutDashboard size={16} />} label={t("Overview", "အနှစ်ချုပ်")} active={view === "overview"} count={undefined} onClick={() => nav("overview")} /><NavButton icon={<Users size={16} />} label={t("Customers", "ဖောက်သည်များ")} active={view === "customers"} count={stats.customers} onClick={() => nav("customers")} /><NavButton icon={<WalletCards size={16} />} label={t("POS sales", "အရောင်း POS")} active={view === "orders"} count={stats.orders} onClick={() => { nav("orders"); setShowOrderForm(true); }} /><NavButton icon={<CalendarClock size={16} />} label={t("Follow-up queue", "နောက်ဆက်တွဲတန်းစီမှု")} active={view === "followups"} count={liveFollowups.length} onClick={() => nav("followups")} /><NavButton icon={<Smartphone size={16} />} label={t("Stock / IMEI", "Stock / IMEI")} active={view === "inventory"} count={products.length} onClick={() => nav("inventory")} /><NavButton icon={<Wrench size={16} />} label={t("Repairs & warranty", "ပြုပြင်ရေး / warranty")} active={view === "repairs"} count={repairs.length} onClick={() => nav("repairs")} /></nav><div className="sidebar-label">{t("System", "စနစ်")}</div><nav className="console-nav"><NavButton icon={<BarChart3 size={16} />} label={t("Analytics", "ခွဲခြမ်းစိတ်ဖြာမှု")} onClick={() => { nav("overview"); toast.info(t("Analytics is shown on Overview.", "Analytics ကို အနှစ်ချုပ်စာမျက်နှာတွင် ပြထားပါသည်။")); }} /><NavButton icon={<Settings2 size={16} />} label={t("Settings", "ဆက်တင်များ")} onClick={() => toast.info(t("Settings will be added after the data model is confirmed.", "Data model အတည်ပြုပြီးနောက် Settings ထည့်ပါမည်။"))} /></nav><div className="sidebar-bottom"><div className="admin-chip"><span>{initials(session.user.email || "AD")}</span><div><strong>{session.user.email?.split("@")[0] || "Admin"}</strong><small>Administrator</small></div></div><button className="logout-button" onClick={() => void onSignOut()}><LogOut size={15} /> {t("Sign out", "ထွက်ရန်")}</button></div></aside><div className="mobile-backdrop" onClick={() => setMobileOpen(false)} /><main className="console-main"><header className="console-header"><button className="mobile-menu-button" onClick={() => setMobileOpen(true)}><Menu size={19} /></button><div><span className="breadcrumb-muted">SMARTFLOW /</span><strong>{view === "overview" ? t("Overview", "အနှစ်ချုပ်") : view === "customers" ? t("Customers", "ဖောက်သည်များ") : view === "orders" ? t("Orders", "အော်ဒါများ") : view === "followups" ? t("Follow-up queue", "နောက်ဆက်တွဲတန်းစီမှု") : view === "inventory" ? t("Inventory", "ဖုန်း stock") : t("Repairs & warranty", "ပြုပြင်ရေး / warranty")}</strong></div><div className="header-actions"><div className="connected-state"><span className={syncing ? "pulse-dot" : "connected-dot"} />{syncing ? t("Syncing", "ချိတ်ဆက်နေ") : t("Supabase connected", "Supabase ချိတ်ဆက်ပြီး")}</div><button className="lang-toggle" onClick={() => setLanguage(language === "en" ? "my" : "en")}>{language === "en" ? "မြန်မာ" : "English"}</button><button className="icon-button" onClick={() => void loadData()} aria-label="Refresh"><RefreshCw size={16} /></button><button className="primary-button" onClick={() => view === "orders" ? setShowOrderForm(true) : view === "followups" ? setShowFollowupForm(true) : view === "inventory" ? setShowProductForm(true) : view === "repairs" ? setShowRepairForm(true) : setShowCustomerForm(true)}><Plus size={16} />{view === "orders" ? t("New sale", "အရောင်းအသစ်") : view === "followups" ? t("New follow-up", "နောက်ဆက်တွဲအသစ်") : view === "inventory" ? t("Add device", "ဖုန်းထည့်ရန်") : view === "repairs" ? t("New repair", "ပြုပြင်ရေးအသစ်") : t("New customer", "ဖောက်သည်အသစ်")}</button></div></header><div className="console-content"><section className="page-heading"><div><span className="kicker">{t("ADMIN COMMAND CENTER", "ADMIN ထိန်းချုပ်ရေးစင်တာ")}</span><h1>{view === "overview" ? t("Your shop, at a glance.", "ဆိုင်အခြေအနေကို တစ်ချက်တည်းကြည့်ပါ။") : view === "customers" ? t("Customer records, without the noise.", "မလိုအပ်တာမပါသော ဖောက်သည်မှတ်တမ်းများ။") : view === "orders" ? t("Move every sale forward.", "အရောင်းတိုင်းကို ရှေ့ဆက်ရွှေ့ပါ။") : view === "followups" ? t("Return to the conversations that matter.", "အရေးကြီးသော ဆက်သွယ်မှုများဆီ ပြန်သွားပါ။") : view === "inventory" ? t("Know every device on the shelf.", "စင်ပေါ်က ဖုန်းတိုင်းကို သိမ်းဆည်းစီမံပါ။") : t("Keep every repair accountable.", "ပြုပြင်ရေးတိုင်းကို စနစ်တကျ ထိန်းချုပ်ပါ။")}</h1><p>{t("A focused command center for devices, sales, customers, and after-sales care.", "ဖုန်း stock၊ အရောင်း၊ ဖောက်သည်နှင့် ရောင်းပြီးနောက်ဝန်ဆောင်မှုအတွက် workspace တစ်ခုတည်း။")}</p></div><div className="heading-actions"><button className="secondary-button" onClick={exportCsv}><Archive size={15} />{t("Export", "ထုတ်ယူရန်")}</button><button className="secondary-button" onClick={() => toast.info(t("Alerts are not sending yet: connect Telegram or email credentials in the deployment settings.", "Alerts မပို့သေးပါ: deployment settings တွင် Telegram သို့မဟုတ် email credentials ချိတ်ဆက်ပါ။"))}><Bell size={15} />{t("Alerts", "အသိပေးချက်များ")}</button></div></section>{view === "overview" && <PhoneShopHome stats={stats} orders={orders} customers={customers} followups={followups} products={products} repairs={repairs} language={language} onNewSale={() => setShowOrderForm(true)} onNewProduct={() => setShowProductForm(true)} onNewRepair={() => setShowRepairForm(true)} onOpenInventory={() => nav("inventory")} onOpenRepairs={() => nav("repairs")} />}{view === "inventory" && <InventoryView products={products} language={language} loading={loading} onNew={() => setShowProductForm(true)} />}{view === "repairs" && <RepairView repairs={repairs} language={language} loading={loading} onNew={() => setShowRepairForm(true)} onOpen={(customer) => setSelectedCustomer(customer)} />}{view === "customers" && <CustomerView customers={filteredCustomers} query={query} setQuery={setQuery} statusFilter={statusFilter} setStatusFilter={setStatusFilter} language={language} loading={loading} onOpen={(customer) => setSelectedCustomer(customer)} onNew={() => setShowCustomerForm(true)} />}{view === "orders" && <OrderView orders={filteredOrders} query={query} setQuery={setQuery} orderFilter={orderFilter} setOrderFilter={setOrderFilter} language={language} loading={loading} onStatus={updateOrder} onNew={() => setShowOrderForm(true)} />}{view === "followups" && <FollowupView followups={liveFollowups} activities={activities} customers={customers} language={language} onOpen={(customer) => setSelectedCustomer(customer)} onNew={() => setShowFollowupForm(true)} />}</div></main>{selectedCustomer && <CustomerDrawer customer={selectedCustomer} activities={activities.filter((activity) => activity.customer_id === selectedCustomer.id)} followups={followupRecords.filter((followup) => followup.customer_id === selectedCustomer.id)} language={language} onClose={() => setSelectedCustomer(null)} onEdit={() => { setEditing(selectedCustomer); setSelectedCustomer(null); setShowCustomerForm(true); }} onAddFollowup={() => setShowFollowupForm(true)} />}{showCustomerForm && <CustomerForm initial={editing} language={language} onClose={() => { setShowCustomerForm(false); setEditing(null); }} onSave={saveCustomer} />}{showOrderForm && <OrderForm customers={customers} language={language} onClose={() => setShowOrderForm(false)} onSave={saveOrder} />}{showFollowupForm && <FollowupForm customers={customers} language={language} onClose={() => setShowFollowupForm(false)} onSave={saveFollowup} />}{showProductForm && <ProductForm language={language} onClose={() => setShowProductForm(false)} onSave={saveProduct} />}{showRepairForm && <RepairForm customers={customers} language={language} onClose={() => setShowRepairForm(false)} onSave={saveRepair} />}</div>;
}

function NavButton({ icon, label, count, active, onClick }: { icon: ReactNode; label: string; count?: number; active?: boolean; onClick: () => void }) { return <button className={`console-nav-item ${active ? "active" : ""}`} onClick={onClick}>{icon}<span>{label}</span>{count !== undefined && <b>{count}</b>}</button>; }
function StatCard({ icon, label, value, note, accent }: { icon: ReactNode; label: string; value: string | number; note: string; accent: string }) { return <div className={`console-stat accent-${accent}`}><div className="stat-top"><span>{icon}</span><ArrowUpRight size={15} /></div><small>{label}</small><strong>{value}</strong><em>{note}</em></div>; }
// Phone-shop-first home: this is the visible operating surface for a handset store.
function PhoneShopHome({ stats, orders, customers, followups, products, repairs, language, onNewSale, onNewProduct, onNewRepair, onOpenInventory, onOpenRepairs }: { stats: { customers: number; active: number; orders: number; revenue: number; units: number; lowStock: number; openRepairs: number }; orders: Order[]; customers: Customer[]; followups: Customer[]; products: Product[]; repairs: Repair[]; language: "en" | "my"; onNewSale: () => void; onNewProduct: () => void; onNewRepair: () => void; onOpenInventory: () => void; onOpenRepairs: () => void }) {
  const t = (en: string, my: string) => language === "my" ? my : en;
  const lowStock = products.filter((product) => Number(product.quantity || 0) <= Number(product.reorder_level || 0)).slice(0, 5);
  const recentSales = orders.filter((order) => order.status !== "cancelled").slice(0, 5);
  const dueRepairs = repairs.filter((repair) => repair.status !== "collected").slice(0, 4);
  return <div className="shop-home">
    <section className="shop-kpi-grid">
      <StatCard icon={<CircleDollarSign size={18} />} label={t("Today's sales", "ယနေ့အရောင်း")} value={money(stats.revenue)} note={t("live order value", "လက်ရှိ order တန်ဖိုး")} accent="cyan" />
      <StatCard icon={<Smartphone size={18} />} label={t("Units on shelf", "စင်ပေါ်ရှိ ဖုန်းများ")} value={stats.units} note={t(`${stats.lowStock} low-stock alerts`, `${stats.lowStock} ခု stock နည်းနေ`)} accent="green" />
      <StatCard icon={<Package size={18} />} label={t("Sales tickets", "အရောင်းစာရင်း")} value={stats.orders} note={t("all recorded sales", "မှတ်တမ်းတင်ထားသမျှ")} accent="amber" />
      <StatCard icon={<Wrench size={18} />} label={t("Repair queue", "ပြုပြင်ရေးတန်းစီမှု")} value={stats.openRepairs} note={t("after-sales service", "ရောင်းပြီးနောက် service")} accent="violet" />
    </section>
    <section className="shop-quick-strip">
      <div><span className="kicker">{t("SHOP FLOOR ACTIONS", "ဆိုင်လုပ်ငန်း အမြန်လုပ်ဆောင်ချက်များ")}</span><h2>{t("Run the counter from one screen.", "ဆိုင်ကောင်တာလုပ်ငန်းကို တစ်နေရာတည်းမှ စီမံပါ။")}</h2></div>
      <div className="shop-actions"><button className="shop-action primary" onClick={onNewSale}><WalletCards size={18} /><span>{t("New sale", "အရောင်းအသစ်")}<small>{t("POS entry", "POS မှတ်တမ်း")}</small></span><ArrowUpRight size={15} /></button><button className="shop-action" onClick={onNewProduct}><Boxes size={18} /><span>{t("Receive stock", "Stock လက်ခံရန်")}<small>{t("SKU + IMEI", "SKU + IMEI")}</small></span><ArrowUpRight size={15} /></button><button className="shop-action" onClick={onNewRepair}><Wrench size={18} /><span>{t("Open repair", "ပြုပြင်ရေးဖွင့်ရန်")}<small>{t("Warranty ticket", "Warranty မှတ်တမ်း")}</small></span><ArrowUpRight size={15} /></button></div>
    </section>
    <section className="shop-content-grid">
      <div className="shop-panel shop-stock-panel"><div className="shop-panel-head"><div><span className="kicker">{t("STOCK WATCH", "STOCK စောင့်ကြည့်မှု")}</span><h3>{t("Low stock / reorder", "Stock နည်းပြီး ပြန်မှာရန်")}</h3></div><button className="text-link" onClick={onOpenInventory}>{t("View all", "အားလုံးကြည့်ရန်")} <ChevronRight size={14} /></button></div>{lowStock.length ? lowStock.map((product) => <div className="shop-row" key={product.id}><span className="device-orb"><Smartphone size={16} /></span><div><strong>{product.brand} {product.model}</strong><small>{product.storage} · {product.imei || t("IMEI pending", "IMEI မထည့်ရသေး")}</small></div><b className="stock-low">{product.quantity}</b></div>) : <EmptyInline text={t("No low-stock devices from Supabase.", "Supabase မှ stock နည်းသော ဖုန်းမရှိပါ။")} />}</div>
      <div className="shop-panel shop-sales-panel"><div className="shop-panel-head"><div><span className="kicker">{t("RECENT SALES", "နောက်ဆုံးအရောင်းများ")}</span><h3>{t("Counter activity", "ကောင်တာ လုပ်ဆောင်ချက်")}</h3></div><span className="live-pill"><i className="connected-dot" /> LIVE</span></div>{recentSales.length ? recentSales.map((order) => <div className="shop-row" key={order.id}><span className="sale-icon"><CircleDollarSign size={16} /></span><div><strong>{order.order_number}</strong><small>{order.customer?.full_name || t("Walk-in customer", "ဆိုင်လာဖောက်သည်")} · {order.channel}</small></div><b>{money(Number(order.amount || 0))}</b></div>) : <EmptyInline text={t("No sales recorded yet.", "အရောင်းမှတ်တမ်း မရှိသေးပါ။")} />}</div>
      <div className="shop-panel shop-repair-panel"><div className="shop-panel-head"><div><span className="kicker">{t("SERVICE DESK", "SERVICE DESK")}</span><h3>{t("Warranty & repairs due", "Warranty နှင့် ပြုပြင်ရေး")}</h3></div><button className="text-link" onClick={onOpenRepairs}>{t("Open queue", "တန်းစီမှုဖွင့်ရန်")} <ChevronRight size={14} /></button></div>{dueRepairs.length ? dueRepairs.map((repair) => <div className="shop-row" key={repair.id}><span className="repair-icon"><Wrench size={16} /></span><div><strong>{repair.device_name}</strong><small>{repair.issue} · {repair.status}</small></div><b>{repair.due_at ? formatDate(repair.due_at, language).split(",")[0] : t("No due date", "ရက်မသတ်မှတ်ရသေး")}</b></div>) : <EmptyInline text={t("No open repair tickets from Supabase.", "Supabase မှ ဖွင့်ထားသော repair မရှိပါ။")} />}</div>
      <div className="shop-panel shop-signal-panel"><div className="shop-panel-head"><div><span className="kicker">{t("CUSTOMER SIGNAL", "ဖောက်သည် signal")}</span><h3>{t("Follow-up pulse", "Follow-up အခြေအနေ")}</h3></div><Activity size={18} /></div><div className="signal-number">{followups.length}<small>{t("customer leads need a touch", "ဖောက်သည် lead များ follow-up လိုနေ")}</small></div><div className="signal-meter"><span style={{ width: `${Math.min(100, followups.length * 14)}%` }} /></div><p>{t("Keep warranty reminders and post-sale care moving.", "Warranty reminder နှင့် ရောင်းပြီးနောက် care ကို ဆက်လက်လုပ်ဆောင်ပါ။")}</p></div>
    </section>
  </div>;
}

function Overview({ stats, orders, customers, followups, products, repairs, language, onOrderStatus, onOpenCustomer }: { stats: { customers: number; active: number; orders: number; revenue: number; units: number; lowStock: number; openRepairs: number }; orders: Order[]; customers: Customer[]; followups: Customer[]; products: Product[]; repairs: Repair[]; language: "en" | "my"; onOrderStatus: (order: Order, status: OrderStatus) => void; onOpenCustomer: (customer: Customer) => void }) { const t = (en: string, my: string) => language === "my" ? my : en; const channelCounts = channels.map((channel) => ({ channel, count: orders.filter((order) => order.channel === channel).length })).filter((item) => item.count); const totalChannels = channelCounts.reduce((sum, item) => sum + item.count, 0) || 1; return <><section className="stat-grid"><StatCard icon={<Users size={17} />} label={t("Customers", "ဖောက်သည်များ")} value={stats.customers} note={t("active records", "လုပ်ဆောင်နေသော မှတ်တမ်း") } accent="cyan" /><StatCard icon={<Activity size={17} />} label={t("Active relationships", "လုပ်ဆောင်နေသော ဖောက်သည်") } value={stats.active} note={t("need attention", "အာရုံစိုက်ရန်လို") } accent="green" /><StatCard icon={<ClipboardList size={17} />} label={t("Orders", "အော်ဒါများ")} value={stats.orders} note={t("all recorded orders", "မှတ်တမ်းတင်ထားသမျှ") } accent="amber" /><StatCard icon={<CircleDollarSign size={17} />} label={t("Sales value", "အရောင်းတန်ဖိုး")} value={money(stats.revenue)} note={t("excluding cancelled", "ပယ်ဖျက်ထားသည်များမပါ") } accent="violet" /><StatCard icon={<Smartphone size={17} />} label={t("Units in stock", "stock ထဲရှိ ဖုန်းအရေအတွက်")} value={stats.units} note={stats.lowStock ? `${stats.lowStock} ${t("low-stock alerts", "stock နည်းသတိပေးချက်")}` : t("stock levels healthy", "stock အခြေအနေကောင်း") } accent="cyan" /><StatCard icon={<Wrench size={17} />} label={t("Open repairs", "ဖွင့်ထားသော ပြုပြင်ရေး") } value={stats.openRepairs} note={t("warranty & service queue", "warranty နှင့် service တန်းစီမှု") } accent="amber" /></section><div className="analytics-grid"><section className="data-panel"><PanelTitle kicker={t("ORDER FLOW", "အော်ဒါလမ်းကြောင်း")} title={t("Where orders are right now", "လက်ရှိအော်ဒါများ၏ အခြေအနေ")} /><div className="status-bars">{orderStatuses.map((status) => { const count = orders.filter((order) => order.status === status).length; const pct = orders.length ? Math.round((count / orders.length) * 100) : 0; return <div className="status-bar-row" key={status}><div><span className={toneClass(orderMeta[status].tone)}>{language === "my" ? orderMeta[status].my : orderMeta[status].en}</span><b>{count}</b></div><div className="bar-track"><i className={`bar-fill fill-${orderMeta[status].tone}`} style={{ width: `${Math.max(pct, count ? 4 : 0)}%` }} /></div><small>{pct}%</small></div>; })}</div>{!orders.length && <EmptyInline text={t("Order analytics will appear when Supabase orders are added.", "Supabase တွင် အော်ဒါများထည့်ပြီးနောက် analytics ပေါ်လာပါမည်။")} />}</section><section className="data-panel"><PanelTitle kicker={t("CHANNEL MIX", "CHANNEL ခွဲခြမ်းစိတ်ဖြာမှု")} title={t("Where conversations begin", "ဆက်သွယ်မှုများ စတင်ရာနေရာ")} /><div className="channel-list">{channelCounts.map(({ channel, count }) => <div className="channel-row" key={channel}><span>{channel}</span><div className="bar-track"><i className="bar-fill fill-cyan" style={{ width: `${(count / totalChannels) * 100}%` }} /></div><b>{count}</b></div>)}</div>{!channelCounts.length && <EmptyInline text={t("Channel analytics will appear when orders are connected.", "Order များနှင့် channel data ချိတ်ပြီးနောက် analytics ပေါ်လာပါမည်။")} />}</section></div><section className="workflow-panel"><PanelTitle kicker={t("WORKFLOW STATUS", "လုပ်ငန်းစဉ်အခြေအနေ")} title={t("From first message to completed order", "ပထမဆုံး message မှ order ပြီးစီးသည်အထိ")} /><div className="workflow-steps"><WorkflowStep icon={<Mail size={15} />} label={t("Conversation", "ဆက်သွယ်မှု")} note="Messenger / Viber" done={orders.length > 0} /><WorkflowStep icon={<Users size={15} />} label={t("Customer record", "ဖောက်သည်မှတ်တမ်း")} note="CRM" done={customers.length > 0} /><WorkflowStep icon={<ClipboardList size={15} />} label={t("Order created", "အော်ဒါတင်ပြီး")} note="Supabase" done={orders.length > 0} /><WorkflowStep icon={<Clock3 size={15} />} label={t("Follow-up", "နောက်ဆက်တွဲ")} note={`${followups.length} open`} done={followups.length === 0 && orders.length > 0} /><WorkflowStep icon={<Check size={15} />} label={t("Completed", "ပြီးစီး")} note={`${orders.filter((o) => o.status === "completed").length} orders`} done={orders.some((o) => o.status === "completed")} /></div></section><div className="lower-grid"><section className="data-panel"><PanelTitle kicker={t("RECENT ORDERS", "လတ်တလောအော်ဒါများ")} title={t("Keep the queue moving", "အော်ဒါတန်းစီမှုကို ရှေ့ဆက်ပါ")} /><div className="compact-list">{orders.slice(0, 5).map((order) => <div className="compact-row" key={order.id}><div className="compact-avatar">{initials(order.customer?.full_name || "OR")}</div><div className="compact-main"><strong>{order.customer?.full_name || "Unknown customer"}</strong><small>{order.order_number} · {order.channel}</small></div><span className={toneClass(orderMeta[order.status].tone)}>{language === "my" ? orderMeta[order.status].my : orderMeta[order.status].en}</span><select value={order.status} onChange={(e) => onOrderStatus(order, e.target.value as OrderStatus)} aria-label="Order status">{orderStatuses.map((status) => <option key={status} value={status}>{orderMeta[status].en}</option>)}</select></div>)}{!orders.length && <EmptyInline text={t("No orders have been added yet.", "အော်ဒါမှတ်တမ်း မရှိသေးပါ။")} />}</div></section><section className="data-panel"><PanelTitle kicker={t("NEXT ACTION", "နောက်ထပ်လုပ်ဆောင်ရန်")} title={t("Follow-up queue", "နောက်ဆက်တွဲတန်းစီမှု")} /><div className="compact-list">{followups.slice(0, 5).map((customer) => <button className="follow-row" key={customer.id} onClick={() => onOpenCustomer(customer)}><span className="follow-line" /><div><strong>{customer.full_name}</strong><small>{customer.company || customer.source}</small></div><ChevronRight size={15} /></button>)}{!followups.length && <EmptyInline text={t("No follow-ups are waiting.", "နောက်ဆက်တွဲလုပ်ရန် မရှိသေးပါ။")} />}</div></section></div></>; }
function WorkflowStep({ icon, label, note, done }: { icon: ReactNode; label: string; note: string; done: boolean }) { return <div className={`workflow-step ${done ? "done" : ""}`}><span>{done ? <Check size={14} /> : icon}</span><strong>{label}</strong><small>{note}</small></div>; }
function PanelTitle({ kicker, title }: { kicker: string; title: string }) { return <div className="panel-title"><div><span className="kicker">{kicker}</span><h2>{title}</h2></div><MoreButton /></div>; }
function MoreButton() { return <button className="more-button" aria-label="More options"><span /><span /><span /></button>; }
function EmptyInline({ text }: { text: string }) { return <div className="empty-inline"><Archive size={18} /><span>{text}</span></div>; }

function Modal({ title, onClose, children }: { title: string; onClose: () => void; children: ReactNode }) { return <><div className="modal-backdrop" onClick={onClose} /><section className="form-modal compact-modal"><div className="modal-header"><div><span className="kicker">SMARTFLOW / PHONE SHOP</span><h2>{title}</h2></div><button type="button" className="icon-button" onClick={onClose} aria-label="Close"><X size={17} /></button></div>{children}</section></>; }
function Field({ label, children }: { label: string; children: ReactNode }) { return <label>{label}{children}</label>; }

function InventoryView({ products, language, loading, onNew }: { products: Product[]; language: "en" | "my"; loading: boolean; onNew: () => void }) { const t = (en: string, my: string) => language === "my" ? my : en; return <section className="data-panel full-panel"><div className="list-toolbar"><div><span className="kicker">{t("DEVICE CATALOG", "ဖုန်း stock စာရင်း")}</span><h2>{products.length} {t("devices tracked", "ဖုန်းမှတ်တမ်း")}</h2></div><div className="toolbar-controls"><div className="inventory-summary"><Boxes size={16} /> {products.filter((product) => product.quantity <= product.reorder_level).length} {t("low stock", "stock နည်း")}</div><button className="secondary-button" onClick={onNew}><Plus size={15} />{t("Add device", "ဖုန်းထည့်ရန်")}</button></div></div><div className="table-wrap"><table><thead><tr><th>{t("Device", "ဖုန်း")}</th><th>SKU / IMEI</th><th>{t("Condition", "အခြေအနေ")}</th><th>{t("Stock", "stock")}</th><th>{t("Price", "စျေးနှုန်း")}</th><th>{t("Warranty", "warranty")}</th></tr></thead><tbody>{products.map((product) => <tr key={product.id}><td><div className="table-person"><span><Smartphone size={15} /></span><div><strong>{product.brand} {product.model}</strong><small>{product.storage} · {product.color}</small></div></div></td><td><strong>{product.sku}</strong><small className="table-sub">{product.imei || t("IMEI not added", "IMEI မထည့်ရသေး")}</small></td><td><span className={toneClass(product.condition === "new" ? "green" : "amber")}>{product.condition}</span></td><td><strong className={product.quantity <= product.reorder_level ? "stock-low" : "stock-ok"}>{product.quantity}</strong><small className="table-sub">{product.quantity <= product.reorder_level ? t("Reorder soon", "ပြန်မှာရန်") : t("Available", "ရရှိနိုင်")}</small></td><td>{money(Number(product.selling_price || 0))}</td><td><span className="warranty-chip"><ShieldCheck size={13} />{product.warranty_months} mo</span></td></tr>)}</tbody></table>{loading && <EmptyInline text={t("Loading inventory…", "ဖုန်း stock များ ဖတ်နေပါသည်…")} />}{!loading && !products.length && <EmptyState title={t("Inventory is empty.", "ဖုန်း stock မရှိသေးပါ။")} text={t("Add real device records with SKU and IMEI to start tracking stock.", "SKU နှင့် IMEI ပါသော ဖုန်းမှတ်တမ်းများကို ထည့်ပြီး stock စတင်စီမံပါ။")} action={onNew} actionLabel={t("Add first device", "ပထမဆုံး ဖုန်းထည့်ရန်")} />}</div></section>; }

function RepairView({ repairs, language, loading, onNew, onOpen }: { repairs: Repair[]; language: "en" | "my"; loading: boolean; onNew: () => void; onOpen: (customer: Customer) => void }) { const t = (en: string, my: string) => language === "my" ? my : en; const repairMeta: Record<Repair["status"], { en: string; my: string; tone: string }> = { received: { en: "Received", my: "လက်ခံပြီး", tone: "cyan" }, diagnosing: { en: "Diagnosing", my: "စစ်ဆေးနေ", tone: "amber" }, repairing: { en: "Repairing", my: "ပြုပြင်နေ", tone: "violet" }, ready: { en: "Ready", my: "အသင့်", tone: "green" }, collected: { en: "Collected", my: "ယူပြီး", tone: "green" } }; return <section className="data-panel full-panel"><div className="list-toolbar"><div><span className="kicker">{t("SERVICE DESK", "ပြုပြင်ရေးနှင့် warranty")}</span><h2>{repairs.length} {t("open tickets", "ဖွင့်ထားသော ticket")}</h2></div><button className="secondary-button" onClick={onNew}><Wrench size={15} />{t("New repair", "ပြုပြင်ရေးအသစ်")}</button></div><div className="table-wrap"><table><thead><tr><th>{t("Device", "ဖုန်း")}</th><th>{t("Customer", "ဖောက်သည်")}</th><th>{t("Issue", "ပြဿနာ")}</th><th>{t("Status", "အခြေအနေ")}</th><th>{t("Estimate", "ခန့်မှန်းကုန်ကျစရိတ်")}</th><th>{t("Due", "အပ်ရမည့်နေ့")}</th></tr></thead><tbody>{repairs.map((repair) => <tr key={repair.id} onClick={() => repair.customer && onOpen(repair.customer)}><td><strong>{repair.device_name}</strong><small className="table-sub">{repair.imei || t("IMEI not added", "IMEI မထည့်ရသေး")}</small></td><td>{repair.customer?.full_name || t("Unknown", "မသိရသေး")}</td><td><span className="issue-cell">{repair.issue}</span></td><td><span className={toneClass(repairMeta[repair.status].tone)}>{language === "my" ? repairMeta[repair.status].my : repairMeta[repair.status].en}</span></td><td>{money(Number(repair.estimated_cost || 0))}</td><td>{repair.due_at ? formatDate(repair.due_at, language) : "—"}</td></tr>)}</tbody></table>{loading && <EmptyInline text={t("Loading repair queue…", "ပြုပြင်ရေးတန်းစီမှု ဖတ်နေပါသည်…")} />}{!loading && !repairs.length && <EmptyState title={t("No open repair tickets.", "ဖွင့်ထားသော ပြုပြင်ရေးမရှိသေးပါ။")} text={t("Create a repair ticket when a device comes in for service or warranty.", "service သို့မဟုတ် warranty အတွက် ဖုန်းလက်ခံသောအခါ ticket ဖန်တီးပါ။")} action={onNew} actionLabel={t("Create repair ticket", "ပြုပြင်ရေး ticket ဖန်တီးရန်")} />}</div></section>; }

function ProductForm({ language, onClose, onSave }: { language: "en" | "my"; onClose: () => void; onSave: (input: Omit<Product, "id" | "created_at">) => Promise<void> }) { const t = (en: string, my: string) => language === "my" ? my : en; const [form, setForm] = useState({ sku: "", brand: "", model: "", storage: "", color: "", condition: "new" as Product["condition"], imei: "", cost_price: "", selling_price: "", quantity: "1", reorder_level: "1", warranty_months: "12", supplier_name: "" }); const submit = (event: React.FormEvent) => { event.preventDefault(); if (!form.sku.trim() || !form.brand.trim() || !form.model.trim()) return toast.error(t("SKU, brand, and model are required.", "SKU၊ brand နှင့် model ဖြည့်ရန်လိုပါသည်။")); void onSave({ ...form, sku: form.sku.trim(), brand: form.brand.trim(), model: form.model.trim(), cost_price: Number(form.cost_price || 0), selling_price: Number(form.selling_price || 0), quantity: Number(form.quantity || 0), reorder_level: Number(form.reorder_level || 0), warranty_months: Number(form.warranty_months || 0) }); }; return <Modal title={t("Add device to inventory", "ဖုန်း stock ထဲသို့ ထည့်ရန်")} onClose={onClose}><form className="form-grid" onSubmit={submit}><Field label="SKU"><input value={form.sku} onChange={(e) => setForm({ ...form, sku: e.target.value })} placeholder="IPH-15-128-BLK" /></Field><Field label={t("Brand", "အမှတ်တံဆိပ်")}><input value={form.brand} onChange={(e) => setForm({ ...form, brand: e.target.value })} placeholder="Apple" /></Field><Field label={t("Model", "မော်ဒယ်")}><input value={form.model} onChange={(e) => setForm({ ...form, model: e.target.value })} placeholder="iPhone 15" /></Field><Field label={t("Storage", "သိုလှောင်မှု")}><input value={form.storage} onChange={(e) => setForm({ ...form, storage: e.target.value })} placeholder="128GB" /></Field><Field label={t("Color", "အရောင်")}><input value={form.color} onChange={(e) => setForm({ ...form, color: e.target.value })} placeholder="Black" /></Field><Field label={t("Condition", "အခြေအနေ")}><select value={form.condition} onChange={(e) => setForm({ ...form, condition: e.target.value as Product["condition"] })}><option value="new">New</option><option value="used">Used</option><option value="refurbished">Refurbished</option></select></Field><Field label="IMEI"><input value={form.imei} onChange={(e) => setForm({ ...form, imei: e.target.value })} placeholder="Optional" /></Field><Field label={t("Selling price", "ရောင်းစျေး")}><input type="number" min="0" value={form.selling_price} onChange={(e) => setForm({ ...form, selling_price: e.target.value })} /></Field><Field label={t("Cost price", "ဝယ်စျေး")}><input type="number" min="0" value={form.cost_price} onChange={(e) => setForm({ ...form, cost_price: e.target.value })} /></Field><Field label={t("Quantity", "အရေအတွက်")}><input type="number" min="0" value={form.quantity} onChange={(e) => setForm({ ...form, quantity: e.target.value })} /></Field><Field label={t("Reorder level", "ပြန်မှာမည့်အဆင့်")}><input type="number" min="0" value={form.reorder_level} onChange={(e) => setForm({ ...form, reorder_level: e.target.value })} /></Field><Field label={t("Warranty months", "warranty လ")}><input type="number" min="0" value={form.warranty_months} onChange={(e) => setForm({ ...form, warranty_months: e.target.value })} /></Field><Field label={t("Supplier", "ပေးသွင်းသူ")}><input value={form.supplier_name} onChange={(e) => setForm({ ...form, supplier_name: e.target.value })} /></Field><div className="form-actions"><button type="button" className="secondary-button" onClick={onClose}>{t("Cancel", "ပယ်ဖျက်ရန်")}</button><button className="primary-button" type="submit"><Plus size={15} />{t("Save device", "ဖုန်းသိမ်းရန်")}</button></div></form></Modal>; }

function RepairForm({ customers, language, onClose, onSave }: { customers: Customer[]; language: "en" | "my"; onClose: () => void; onSave: (input: Omit<Repair, "id" | "created_at" | "customer">) => Promise<void> }) { const t = (en: string, my: string) => language === "my" ? my : en; const [form, setForm] = useState({ customer_id: customers[0]?.id || "", device_name: "", imei: "", issue: "", status: "received" as Repair["status"], estimated_cost: "", due_at: "", notes: "" }); const submit = (event: React.FormEvent) => { event.preventDefault(); if (!form.customer_id || !form.device_name.trim() || !form.issue.trim()) return toast.error(t("Customer, device, and issue are required.", "ဖောက်သည်၊ ဖုန်းနှင့် ပြဿနာ ဖြည့်ရန်လိုပါသည်။")); void onSave({ ...form, device_name: form.device_name.trim(), issue: form.issue.trim(), estimated_cost: Number(form.estimated_cost || 0), due_at: form.due_at ? new Date(form.due_at).toISOString() : null }); }; return <Modal title={t("Create repair ticket", "ပြုပြင်ရေး ticket ဖန်တီးရန်")} onClose={onClose}><form className="form-grid" onSubmit={submit}><Field label={t("Customer", "ဖောက်သည်")}><select value={form.customer_id} onChange={(e) => setForm({ ...form, customer_id: e.target.value })}><option value="">{t("Select customer", "ဖောက်သည်ရွေးပါ")}</option>{customers.map((customer) => <option key={customer.id} value={customer.id}>{customer.full_name}</option>)}</select></Field><Field label={t("Device", "ဖုန်း")}><input value={form.device_name} onChange={(e) => setForm({ ...form, device_name: e.target.value })} placeholder="iPhone 13 Pro" /></Field><Field label="IMEI"><input value={form.imei} onChange={(e) => setForm({ ...form, imei: e.target.value })} /></Field><Field label={t("Issue", "ပြဿနာ")}><textarea value={form.issue} onChange={(e) => setForm({ ...form, issue: e.target.value })} placeholder={t("Screen, battery, software…", "Screen၊ battery၊ software…")} /></Field><Field label={t("Status", "အခြေအနေ")}><select value={form.status} onChange={(e) => setForm({ ...form, status: e.target.value as Repair["status"] })}><option value="received">Received</option><option value="diagnosing">Diagnosing</option><option value="repairing">Repairing</option><option value="ready">Ready</option></select></Field><Field label={t("Estimated cost", "ခန့်မှန်းကုန်ကျစရိတ်")}><input type="number" min="0" value={form.estimated_cost} onChange={(e) => setForm({ ...form, estimated_cost: e.target.value })} /></Field><Field label={t("Due date", "အပ်ရမည့်နေ့")}><input type="datetime-local" value={form.due_at} onChange={(e) => setForm({ ...form, due_at: e.target.value })} /></Field><Field label={t("Notes", "မှတ်ချက်")}><textarea value={form.notes} onChange={(e) => setForm({ ...form, notes: e.target.value })} /></Field><div className="form-actions"><button type="button" className="secondary-button" onClick={onClose}>{t("Cancel", "ပယ်ဖျက်ရန်")}</button><button className="primary-button" type="submit"><Wrench size={15} />{t("Save ticket", "ticket သိမ်းရန်")}</button></div></form></Modal>; }

function CustomerView({ customers, query, setQuery, statusFilter, setStatusFilter, language, loading, onOpen, onNew }: { customers: Customer[]; query: string; setQuery: (value: string) => void; statusFilter: Status | "all"; setStatusFilter: (value: Status | "all") => void; language: "en" | "my"; loading: boolean; onOpen: (customer: Customer) => void; onNew: () => void }) { const t = (en: string, my: string) => language === "my" ? my : en; return <section className="data-panel full-panel"><div className="list-toolbar"><div><span className="kicker">{t("CUSTOMER INDEX", "ဖောက်သည်စာရင်း")}</span><h2>{customers.length} {t("visible records", "မြင်ရသော မှတ်တမ်း")}</h2></div><div className="toolbar-controls"><div className="search-box"><Search size={15} /><input value={query} onChange={(e) => setQuery(e.target.value)} placeholder={t("Search customers…", "ဖောက်သည်ရှာရန်…")} /></div><select value={statusFilter} onChange={(e) => setStatusFilter(e.target.value as Status | "all")}><option value="all">{t("All statuses", "အခြေအနေအားလုံး")}</option>{Object.entries(statusMeta).map(([key, meta]) => <option key={key} value={key}>{language === "my" ? meta.my : meta.en}</option>)}</select><button className="secondary-button" onClick={() => toast.info(t("Filters are limited to status and search for now.", "လက်ရှိ status နှင့် search filter များကို အသုံးပြုနိုင်ပါသည်။"))}><Filter size={15} />{t("Filter", "စစ်ထုတ်ရန်")}</button></div></div><div className="table-wrap"><table><thead><tr><th>{t("Customer", "ဖောက်သည်")}</th><th>{t("Source", "ရင်းမြစ်")}</th><th>{t("Status", "အခြေအနေ")}</th><th>{t("Last touch", "နောက်ဆုံးဆက်သွယ်မှု")}</th><th /></tr></thead><tbody>{customers.map((customer) => <tr key={customer.id} onClick={() => onOpen(customer)}><td><div className="table-person"><span>{initials(customer.full_name)}</span><div><strong>{customer.full_name}</strong><small>{customer.company || customer.email || t("No company", "ကုမ္ပဏီမရှိ")}</small></div></div></td><td>{customer.source}</td><td><span className={toneClass(statusMeta[customer.status].tone)}>{language === "my" ? statusMeta[customer.status].my : statusMeta[customer.status].en}</span></td><td>{formatDate(customer.last_touch, language)}</td><td><ChevronRight size={16} /></td></tr>)}</tbody></table>{loading && <EmptyInline text={t("Loading Supabase records…", "Supabase မှတ်တမ်းများ ဖတ်နေပါသည်…")} />}{!loading && !customers.length && <EmptyState title={t("Your customer index is empty.", "ဖောက်သည်စာရင်း မရှိသေးပါ။")} text={t("Add the first real customer record to begin tracking the relationship.", "ပထမဆုံး ဖောက်သည်မှတ်တမ်းကို ထည့်ပြီး စတင်စီမံပါ။")} action={onNew} actionLabel={t("Add customer", "ဖောက်သည်ထည့်ရန်")} />}</div></section>; }
function OrderView({ orders, query, setQuery, orderFilter, setOrderFilter, language, loading, onStatus, onNew }: { orders: Order[]; query: string; setQuery: (value: string) => void; orderFilter: OrderStatus | "all"; setOrderFilter: (value: OrderStatus | "all") => void; language: "en" | "my"; loading: boolean; onStatus: (order: Order, status: OrderStatus) => void; onNew: () => void }) { const t = (en: string, my: string) => language === "my" ? my : en; return <section className="data-panel full-panel"><div className="list-toolbar"><div><span className="kicker">{t("ORDER QUEUE", "အော်ဒါတန်းစီမှု")}</span><h2>{orders.length} {t("recorded orders", "မှတ်တမ်းတင်ထားသော အော်ဒါ")}</h2></div><div className="toolbar-controls"><div className="search-box"><Search size={15} /><input value={query} onChange={(e) => setQuery(e.target.value)} placeholder={t("Search order or customer…", "အော်ဒါ သို့မဟုတ် ဖောက်သည်ရှာရန်…")} /></div><select value={orderFilter} onChange={(e) => setOrderFilter(e.target.value as OrderStatus | "all")}><option value="all">{t("All order statuses", "အော်ဒါအခြေအနေအားလုံး")}</option>{orderStatuses.map((status) => <option key={status} value={status}>{language === "my" ? orderMeta[status].my : orderMeta[status].en}</option>)}</select><button className="secondary-button" onClick={onNew}><Plus size={15} />{t("New order", "အော်ဒါအသစ်")}</button></div></div><div className="table-wrap"><table><thead><tr><th>{t("Order", "အော်ဒါ")}</th><th>{t("Customer", "ဖောက်သည်")}</th><th>{t("Channel", "Channel")}</th><th>{t("Amount", "တန်ဖိုး")}</th><th>{t("Status", "အခြေအနေ")}</th></tr></thead><tbody>{orders.map((order) => <tr key={order.id}><td><strong>{order.order_number}</strong><small className="table-sub">{formatDate(order.created_at, language)}</small></td><td>{order.customer?.full_name || t("Unknown", "မသိရသေး")}</td><td>{order.channel}</td><td>{money(Number(order.amount || 0))}</td><td><select className={`status-select ${orderMeta[order.status].tone}`} value={order.status} onChange={(e) => onStatus(order, e.target.value as OrderStatus)}>{orderStatuses.map((status) => <option value={status} key={status}>{language === "my" ? orderMeta[status].my : orderMeta[status].en}</option>)}</select></td></tr>)}</tbody></table>{loading && <EmptyInline text={t("Loading Supabase orders…", "Supabase အော်ဒါများ ဖတ်နေပါသည်…")} />}{!loading && !orders.length && <EmptyState title={t("No orders recorded yet.", "အော်ဒါမှတ်တမ်း မရှိသေးပါ။")} text={t("Create an order after the customer conversation is qualified.", "ဖောက်သည်ဆက်သွယ်မှု အတည်ပြုပြီးနောက် အော်ဒါတစ်ခု ဖန်တီးပါ။")} action={onNew} actionLabel={t("Add order", "အော်ဒါထည့်ရန်")} />}</div></section>; }
function FollowupView({ followups, activities, customers, language, onOpen, onNew }: { followups: FollowUp[]; activities: ActivityItem[]; customers: Customer[]; language: "en" | "my"; onOpen: (customer: Customer) => void; onNew: () => void }) { const t = (en: string, my: string) => language === "my" ? my : en; return <div className="followup-layout"><section className="data-panel"><PanelTitle kicker={t("OPEN LOOPS", "ဖွင့်ထားသော နောက်ဆက်တွဲများ")} title={t("Who needs a next touch", "ဘယ်သူ့ကို ပြန်ဆက်သွယ်ရမလဲ")} /><div className="followup-stack">{followups.map((followup) => <button className="follow-card" key={followup.id} onClick={() => { const customer = customers.find((item) => item.id === followup.customer_id); if (customer) onOpen(customer); }}><span className="follow-line" /><div className="table-person"><span>{initials(followup.customer?.full_name || "FU")}</span><div><strong>{followup.customer?.full_name || t("Unknown customer", "မသိရသေးသော ဖောက်သည်")}</strong><small>{followup.title}</small></div></div><div className="follow-meta"><span className={toneClass(followup.priority === "urgent" || followup.priority === "high" ? "red" : "amber")}>{followup.priority}</span><small>{formatDate(followup.due_at, language)}</small></div><ChevronRight size={16} /></button>)}{!followups.length && <EmptyState title={t("Your follow-up queue is clear.", "နောက်ဆက်တွဲတန်းစီမှု ရှင်းလင်းနေပါသည်။")} text={t("Create a real follow-up reminder from this queue.", "ဤနေရာမှ follow-up reminder တစ်ခု ဖန်တီးပါ။")} action={onNew} actionLabel={t("Add follow-up", "နောက်ဆက်တွဲထည့်ရန်")} />}</div></section><section className="data-panel"><PanelTitle kicker={t("RECENT ACTIVITY", "လတ်တလောလုပ်ဆောင်ချက်")} title={t("Context worth remembering", "မှတ်သားသင့်သော အချက်အလက်")}/><div className="activity-stack">{activities.slice(0, 8).map((activity) => <div className="activity-row" key={activity.id}><span className="activity-dot" /><div><strong>{activity.title}</strong><p>{activity.description}</p><small>{formatDate(activity.activity_at, language)}</small></div></div>)}{!activities.length && <EmptyInline text={t("Activity notes will appear after customer interactions are recorded.", "ဖောက်သည်ဆက်သွယ်မှုများ မှတ်တမ်းတင်ပြီးနောက် activity များ ပေါ်လာပါမည်။")} />}</div></section></div>; }
function FollowupForm({ customers, language, onClose, onSave }: { customers: Customer[]; language: "en" | "my"; onClose: () => void; onSave: (input: Omit<FollowUp, "id" | "created_at" | "updated_at" | "customer">) => Promise<void> }) { const t = (en: string, my: string) => language === "my" ? my : en; const [customerId, setCustomerId] = useState(customers[0]?.id || ""); const [title, setTitle] = useState(""); const [note, setNote] = useState(""); const [dueAt, setDueAt] = useState(""); const [priority, setPriority] = useState<FollowUpPriority>("normal"); const submit = async (event: React.FormEvent) => { event.preventDefault(); if (!customerId || !title.trim() || !dueAt) { toast.error(t("Customer, title, and due date are required.", "ဖောက်သည်၊ ခေါင်းစဉ်နှင့် due date လိုအပ်ပါသည်။")); return; } await onSave({ customer_id: customerId, order_id: null, title: title.trim(), note: note.trim(), due_at: new Date(dueAt).toISOString(), status: "pending", priority }); }; return <div className="modal-backdrop"><form className="modal-card" onSubmit={(event) => void submit(event)}><div className="modal-head"><div><span className="kicker">{t("NEW FOLLOW-UP", "နောက်ဆက်တွဲအသစ်")}</span><h2>{t("Set the next touch.", "နောက်ထပ်ဆက်သွယ်ရန် သတ်မှတ်ပါ။")}</h2></div><button type="button" className="icon-button" onClick={onClose}><X size={16} /></button></div><div className="form-grid"><label>{t("Customer", "ဖောက်သည်")}<select value={customerId} onChange={(event) => setCustomerId(event.target.value)}>{customers.map((customer) => <option value={customer.id} key={customer.id}>{customer.full_name}</option>)}</select></label><label>{t("Due at", "ဆောင်ရွက်ရမည့်အချိန်")}<input type="datetime-local" value={dueAt} onChange={(event) => setDueAt(event.target.value)} /></label><label>{t("Title", "ခေါင်းစဉ်")}<input value={title} onChange={(event) => setTitle(event.target.value)} placeholder={t("Call back about the order", "အော်ဒါအတွက် ပြန်ဆက်သွယ်ရန်")} /></label><label>{t("Priority", "ဦးစားပေးမှု")}<select value={priority} onChange={(event) => setPriority(event.target.value as FollowUpPriority)}>{(["low", "normal", "high", "urgent"] as FollowUpPriority[]).map((item) => <option key={item} value={item}>{item}</option>)}</select></label><label className="field-wide">{t("Note", "မှတ်ချက်")}<textarea value={note} onChange={(event) => setNote(event.target.value)} rows={3} /></label></div><div className="modal-actions"><button type="button" className="secondary-button" onClick={onClose}>{t("Cancel", "မလုပ်တော့ပါ")}</button><button type="submit" className="primary-button"><Plus size={15} />{t("Save follow-up", "နောက်ဆက်တွဲသိမ်းရန်")}</button></div></form></div>; }

function EmptyState({ title, text, action, actionLabel }: { title: string; text: string; action: () => void; actionLabel: string }) { return <div className="empty-state"><Archive size={24} /><h3>{title}</h3><p>{text}</p><button className="primary-button" onClick={action}><Plus size={15} />{actionLabel}</button></div>; }

function CustomerDrawer({ customer, activities, followups, language, onClose, onEdit, onAddFollowup }: { customer: Customer; activities: ActivityItem[]; followups: FollowUp[]; language: "en" | "my"; onClose: () => void; onEdit: () => void; onAddFollowup: () => void }) { const t = (en: string, my: string) => language === "my" ? my : en; return <><div className="drawer-backdrop" onClick={onClose} /><aside className="customer-drawer"><div className="drawer-header"><div><span className="kicker">{t("CUSTOMER RECORD", "ဖောက်သည်မှတ်တမ်း")}</span><h2>{customer.full_name}</h2></div><button className="icon-button" onClick={onClose}><X size={17} /></button></div><div className="drawer-profile"><span>{initials(customer.full_name)}</span><div><strong>{customer.company || t("Independent customer", "တစ်ဦးချင်းဖောက်သည်")}</strong><small>{customer.email || customer.phone || t("No contact detail", "ဆက်သွယ်ရန် မရှိ")}</small></div><button className="icon-button" onClick={onEdit}><Pencil size={15} /></button></div><div className="drawer-actions"><button className="primary-button" onClick={onEdit}><Pencil size={15} />{t("Edit", "ပြင်ရန်")}</button><button className="secondary-button" onClick={() => toast.info(t("Archive action is available after confirmation rules are added.", "အတည်ပြုစည်းမျဉ်းထည့်ပြီးနောက် Archive လုပ်နိုင်ပါမည်။"))}><Archive size={15} />{t("Archive", "သိမ်းရန်")}</button></div><div className="drawer-section"><span className="kicker">{t("DETAILS", "အသေးစိတ်")}</span><dl><div><dt>{t("Status", "အခြေအနေ")}</dt><dd><span className={toneClass(statusMeta[customer.status].tone)}>{language === "my" ? statusMeta[customer.status].my : statusMeta[customer.status].en}</span></dd></div><div><dt>{t("Channel", "Channel")}</dt><dd>{customer.source}</dd></div><div><dt>{t("Phone", "ဖုန်း")}</dt><dd>{customer.phone || "—"}</dd></div><div><dt>{t("Last touch", "နောက်ဆုံးဆက်သွယ်မှု")}</dt><dd>{formatDate(customer.last_touch, language)}</dd></div></dl></div><div className="drawer-section"><span className="kicker">{t("NOTES", "မှတ်ချက်")}</span><p className="drawer-note">{customer.notes || t("No notes added yet.", "မှတ်ချက် မရှိသေးပါ။")}</p></div><div className="drawer-section"><div className="drawer-section-head"><span className="kicker">{t("FOLLOW-UPS", "နောက်ဆက်တွဲများ")}</span><button className="secondary-button compact-button" onClick={onAddFollowup}><Plus size={14} />{t("Add", "ထည့်ရန်")}</button></div><div className="drawer-followups">{followups.map((followup) => <div className="drawer-followup" key={followup.id}><div><strong>{followup.title}</strong><small>{formatDate(followup.due_at, language)}</small></div><span className={toneClass(followup.priority === "urgent" || followup.priority === "high" ? "red" : "amber")}>{followup.status}</span></div>)}{!followups.length && <EmptyInline text={t("No follow-ups scheduled.", "နောက်ဆက်တွဲ မသတ်မှတ်ရသေးပါ။")} />}</div></div><div className="drawer-section"><span className="kicker">{t("ACTIVITY TIMELINE", "လုပ်ဆောင်ချက်မှတ်တမ်း")}</span><div className="activity-stack">{activities.map((activity) => <div className="activity-row" key={activity.id}><span className="activity-dot" /><div><strong>{activity.title}</strong><p>{activity.description}</p><small>{formatDate(activity.activity_at, language)}</small></div></div>)}{!activities.length && <EmptyInline text={t("No activity recorded yet.", "လုပ်ဆောင်ချက်မှတ်တမ်း မရှိသေးပါ။")} />}</div></div></aside></>; }

function CustomerForm({ initial, language, onClose, onSave }: { initial: Customer | null; language: "en" | "my"; onClose: () => void; onSave: (input: Omit<Customer, "id" | "created_at">) => void }) {
  const t = (en: string, my: string) => language === "my" ? my : en;
  const [form, setForm] = useState<Omit<Customer, "id" | "created_at">>({ full_name: initial?.full_name || "", phone: initial?.phone || "", email: initial?.email || "", company: initial?.company || "", status: initial?.status || "lead", source: initial?.source || "Messenger", notes: initial?.notes || "", tags: initial?.tags || [], last_touch: initial?.last_touch || null });
  const [tag, setTag] = useState("");
  const [emailError, setEmailError] = useState("");
  const validateEmail = (value: string) => {
    const normalized = value.trim();
    if (!normalized) return "";
    return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(normalized) ? "" : t("Enter a valid email address.", "မှန်ကန်သော အီးမေးလ်လိပ်စာ ထည့်ပါ။");
  };
  const handleSave = () => {
    const nextEmailError = validateEmail(form.email);
    if (!form.full_name.trim()) {
      toast.error(t("Full name is required.", "အမည် ဖြည့်ရန်လိုအပ်ပါသည်။"));
      return;
    }
    if (nextEmailError) {
      setEmailError(nextEmailError);
      toast.error(nextEmailError);
      return;
    }
    onSave({ ...form, full_name: form.full_name.trim(), email: form.email.trim() });
  };
  return <><div className="modal-backdrop" onClick={onClose} /><section className="form-modal"><div className="modal-header"><div><span className="kicker">{initial ? t("EDIT CUSTOMER", "ဖောက်သည်ပြင်ရန်") : t("NEW CUSTOMER", "ဖောက်သည်အသစ်")}</span><h2>{initial ? t("Update customer context", "ဖောက်သည်အချက်အလက် ပြင်ရန်") : t("Add the next relationship", "ဖောက်သည်အသစ် ထည့်ရန်")}</h2></div><button className="icon-button" onClick={onClose}><X size={17} /></button></div><div className="form-grid"><label>{t("Full name", "အမည်")}<input value={form.full_name} onChange={(e) => setForm({ ...form, full_name: e.target.value })} /></label><label>{t("Company", "ကုမ္ပဏီ")}<input value={form.company} onChange={(e) => setForm({ ...form, company: e.target.value })} /></label><label>{t("Phone", "ဖုန်း")}<input value={form.phone} onChange={(e) => setForm({ ...form, phone: e.target.value })} /></label><label>{t("Email", "အီးမေးလ်")}<input type="email" value={form.email} aria-invalid={Boolean(emailError)} onChange={(e) => { setForm({ ...form, email: e.target.value }); setEmailError(validateEmail(e.target.value)); }} />{emailError && <small className="form-error">{emailError}</small>}</label><label>{t("Channel", "Channel")}<select value={form.source} onChange={(e) => setForm({ ...form, source: e.target.value as Channel })}>{channels.map((channel) => <option key={channel}>{channel}</option>)}</select></label><label>{t("Status", "အခြေအနေ")}<select value={form.status} onChange={(e) => setForm({ ...form, status: e.target.value as Status })}>{Object.keys(statusMeta).map((status) => <option key={status} value={status}>{language === "my" ? statusMeta[status as Status].my : statusMeta[status as Status].en}</option>)}</select></label><label className="full-field">{t("Tags", "Tags")}<div className="tag-input"><div>{form.tags.map((item) => <span key={item}>{item}<button type="button" onClick={() => setForm({ ...form, tags: form.tags.filter((current) => current !== item) })}>×</button></span>)}</div><input value={tag} onChange={(e) => setTag(e.target.value)} onKeyDown={(e) => { if (e.key === "Enter" && tag.trim()) { e.preventDefault(); setForm({ ...form, tags: Array.from(new Set([...form.tags, tag.trim()])) }); setTag(""); } }} placeholder={t("Type tag and press Enter", "Tag ရိုက်ပြီး Enter နှိပ်ပါ")} /></div></label><label className="full-field">{t("Notes", "မှတ်ချက်")}<textarea rows={4} value={form.notes} onChange={(e) => setForm({ ...form, notes: e.target.value })} /></label></div><div className="modal-footer"><button className="secondary-button" onClick={onClose}>{t("Cancel", "မလုပ်တော့ပါ")}</button><button className="primary-button" disabled={!form.full_name.trim() || Boolean(emailError)} onClick={handleSave}><Check size={15} />{t("Save customer", "ဖောက်သည်သိမ်းရန်")}</button></div></section></>;
}
function OrderForm({ customers, language, onClose, onSave }: { customers: Customer[]; language: "en" | "my"; onClose: () => void; onSave: (input: Omit<Order, "id" | "created_at" | "customer">) => void }) { const t = (en: string, my: string) => language === "my" ? my : en; const [form, setForm] = useState({ customer_id: customers[0]?.id || "", order_number: `ORD-${Date.now().toString().slice(-6)}`, amount: "", status: "new" as OrderStatus, channel: customers[0]?.source || "Messenger" as Channel }); return <><div className="modal-backdrop" onClick={onClose} /><section className="form-modal compact-modal"><div className="modal-header"><div><span className="kicker">{t("NEW ORDER", "အော်ဒါအသစ်")}</span><h2>{t("Record the next order", "အော်ဒါမှတ်တမ်းတင်ရန်")}</h2></div><button className="icon-button" onClick={onClose}><X size={17} /></button></div><div className="form-grid"><label className="full-field">{t("Customer", "ဖောက်သည်")}<select value={form.customer_id} onChange={(e) => setForm({ ...form, customer_id: e.target.value })}>{customers.map((customer) => <option value={customer.id} key={customer.id}>{customer.full_name} · {customer.company}</option>)}</select></label><label>{t("Order number", "အော်ဒါနံပါတ်")}<input value={form.order_number} onChange={(e) => setForm({ ...form, order_number: e.target.value })} /></label><label>{t("Amount (MMK)", "တန်ဖိုး (ကျပ်)")}<input type="number" min="0" value={form.amount} onChange={(e) => setForm({ ...form, amount: e.target.value })} /></label><label>{t("Channel", "Channel")}<select value={form.channel} onChange={(e) => setForm({ ...form, channel: e.target.value as Channel })}>{channels.map((channel) => <option key={channel}>{channel}</option>)}</select></label><label>{t("Status", "အခြေအနေ")}<select value={form.status} onChange={(e) => setForm({ ...form, status: e.target.value as OrderStatus })}>{orderStatuses.map((status) => <option key={status} value={status}>{language === "my" ? orderMeta[status].my : orderMeta[status].en}</option>)}</select></label></div><div className="modal-footer"><button className="secondary-button" onClick={onClose}>{t("Cancel", "မလုပ်တော့ပါ")}</button><button className="primary-button" disabled={!form.customer_id || !form.amount} onClick={() => onSave({ ...form, amount: Number(form.amount) })}><Check size={15} />{t("Save order", "အော်ဒါသိမ်းရန်")}</button></div></section></>; }

export default App;
